SELECT ib.ib_income_band_sk, SUM(cs.cs_net_profit) AS total_cs_profit, SUM(ws.ws_net_profit) AS total_ws_profit FROM catalog_sales cs JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN web_sales ws ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk WHERE cs.cs_sold_date_sk = 2450818 AND ws.ws_sold_date_sk = 2452224 AND cs.cs_quantity > 27 AND EXISTS (SELECT 1 FROM web_sales ws_sub WHERE ws_sub.ws_item_sk = cs.cs_item_sk AND ws_sub.ws_quantity > 84) GROUP BY ib.ib_income_band_sk HAVING SUM(cs.cs_net_profit) > -565.11 AND SUM(ws.ws_net_profit) > -2550.24 ORDER BY ib.ib_income_band_sk
